shared_html.shared_css:
/* ============ Shared Header ============ */

.site-nav {
  position: relative;
  background: var(--bg);
  border-bottom: 1px solid var(--primary);
  font-family: 'Source Sans 3', sans-serif;
  color: var(--text);
}

.site-nav__inner {
  max-width: 78rem;
  margin: 0 auto;
  padding: 1.6rem 2rem 1.2rem;
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: end;
  gap: 2rem;
}

.site-nav__wordmark {
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: var(--primary);
  line-height: 1;
}

.site-nav__kicker {
  font-family: 'Source Sans 3', sans-serif;
  font-size: 0.68rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--secondary);
  margin-bottom: 0.5rem;
}

.site-nav__title {
  font-family: 'Fraunces', serif;
  font-weight: 600;
  font-size: clamp(1.6rem, 2.4vw, 2.2rem);
  letter-spacing: 0.02em;
  color: var(--primary);
}

.site-nav__sub {
  font-family: 'Fraunces', serif;
  font-style: italic;
  font-size: 0.95rem;
  color: var(--text);
  margin-top: 0.35rem;
}

.site-nav__nav {
  justify-self: end;
}

.site-nav__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0;
}

.site-nav__list li + li::before {
  content: "✦";
  color: var(--accent);
  margin: 0 0.65rem;
  font-size: 0.7rem;
  vertical-align: middle;
}

.site-nav__list a {
  font-family: 'Fraunces', serif;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--primary);
  text-decoration: none;
  padding: 0.25rem 0;
  border-bottom: 1px solid transparent;
  transition: color 160ms ease, border-color 160ms ease;
}

.site-nav__list a:hover,
.site-nav__list a[aria-current="page"] {
  color: var(--text-emphasis);
  border-bottom-color: var(--accent);
}

.site-nav__rule {
  height: 6px;
  background:
    linear-gradient(to right,
      var(--secondary) 0 16.66%,
      var(--accent)    16.66% 33.33%,
      var(--primary)   33.33% 50%,
      var(--accent)    50% 66.66%,
      var(--secondary) 66.66% 83.33%,
      var(--primary)   83.33% 100%);
  border-top: 1px solid var(--primary);
  border-bottom: 1px solid var(--primary);
}

@media (max-width: 760px) {
  .site-nav__inner {
    grid-template-columns: 1fr;
    gap: 1rem;
  }
  .site-nav__nav { justify-self: start; }
  .site-nav__list { gap: 0.25rem 0; }
}

/* ============ Shared Footer ============ */

.site-footer {
  margin-top: 6rem;
  background: var(--bg);
  color: var(--text);
  font-family: 'Source Sans 3', sans-serif;
  border-top: 1px solid var(--primary);
}

/* Arcade of pointed arches in miniature */
.site-footer__arcade {
  display: flex;
  height: 36px;
  border-bottom: 1px solid var(--primary);
  background: var(--surface);
}

.site-footer__arcade span {
  flex: 1;
  position: relative;
  border-right: 1px solid var(--primary);
}

.site-footer__arcade span:last-child {
  border-right: none;
}

.site-footer__arcade span::before {
  content: "";
  position: absolute;
  left: 14%;
  right: 14%;
  bottom: 0;
  height: 28px;
  background: var(--secondary);
  clip-path: polygon(0% 100%, 0% 55%, 50% 0%, 100% 55%, 100% 100%);
}

.site-footer__inner {
  max-width: 78rem;
  margin: 0 auto;
  padding: 3rem 2rem 1.5rem;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2.5rem;
}

.site-footer__col h3 {
  font-family: 'Fraunces', serif;
  font-weight: 600;
  font-size: 0.78rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  margin: 0 0 0.9rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--accent);
}

.site-footer__col p {
  margin: 0 0 0.9rem;
  font-size: 0.95rem;
  line-height: 1.6;
}

.site-footer__col ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.site-footer__col li {
  margin-bottom: 0.35rem;
}

.site-footer__col a {
  color: var(--primary);
  text-decoration: none;
  font-size: 0.95rem;
  border-bottom: 1px solid transparent;
}

.site-footer__col a:hover {
  color: var(--text-emphasis);
  border-bottom-color: var(--accent);
}

.site-footer__seal {
  text-align: center;
}

.site-footer__fleur {
  width: 56px;
  height: 56px;
  margin: 0 auto 0.75rem;
  background-color: var(--accent);
  -webkit-mask: url('svg/fleur-de-lis.svg') center/contain no-repeat;
          mask: url('svg/fleur-de-lis.svg') center/contain no-repeat;
  animation: fleur-pulse 4s ease-in-out infinite;
}

@keyframes fleur-pulse {
  0%, 100% { transform: scale(1);    opacity: 0.92; }
  50%      { transform: scale(1.08); opacity: 1;    }
}

.site-footer__motto {
  font-family: 'Fraunces', serif;
  font-style: italic;
  font-size: 1.05rem;
  color: var(--text-emphasis);
  margin: 0 0 0.75rem;
}

.site-footer__fine {
  font-size: 0.82rem;
  line-height: 1.55;
  color: var(--text);
  opacity: 0.85;
}

.site-footer__colophon {
  max-width: 78rem;
  margin: 0 auto;
  padding: 1.25rem 2rem 2rem;
  border-top: 1px solid var(--primary);
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  text-align: center;
  color: var(--text);
  opacity: 0.8;
}

@media (max-width: 880px) {
  .site-footer__inner {
    grid-template-columns: repeat(2, 1fr);
    gap: 2rem;
  }
}

@media (max-width: 520px) {
  .site-footer__inner {
    grid-template-columns: 1fr;
  }
  .site-footer__arcade span:nth-child(n+7) { display: none; }
}
